const KB = {
  Plastico: 'Plástico (contenedor BLANCO): botellas PET, envases y bolsas limpias y secas. Aplástalos para ahorrar espacio.',
  Papel: 'Papel y cartón (contenedor AZUL): cajas, periódicos y hojas limpias. Si está grasoso o mojado ya no es reciclable.',
  Vidrio: 'Vidrio (contenedor VERDE): botellas y frascos sin tapa. Los focos y espejos NO van aquí.',
  Metal: 'Metales (contenedor AMARILLO): latas de aluminio y conservas, enjuagadas. El metal se recicla infinitas veces.',
  Organico: 'Orgánicos (contenedor MARRÓN): restos de fruta, verdura y cáscaras. Se convierten en compost.',
  NoAprovechable: 'No aprovechables (contenedor NEGRO): papel higiénico, envolturas metalizadas y residuos sucios. Van al relleno sanitario.',
  Peligroso: 'Peligrosos (contenedor ROJO): pilas, focos fluorescentes y medicinas. Contienen metales pesados: nunca a la basura común.'
};
const rows = $input.all().map(i => i.json).filter(r => r.VC_MES && r.VC_MES !== 'TOTAL');
let aprov = 0, noAprov = 0;
for (const r of rows) { aprov += parseFloat(r.MO_RESIDUOS_APROVECHABLES); noAprov += parseFloat(r.MO_RESIDUOS_NO_APROVECHABLES); }
const tasa = Math.round(10000 * aprov / (aprov + noAprov)) / 100;
const ev = $('Evento reciclaje').first().json.body;
const s = $getWorkflowStaticData('global');
s.correctos = (s.correctos || 0) + (ev.correcto ? 1 : 0);
s.incorrectos = (s.incorrectos || 0) + (ev.correcto ? 0 : 1);
s.porTipo = s.porTipo || {};
s.porTipo[ev.tipo] = (s.porTipo[ev.tipo] || 0) + 1;
s.eventos = [{ ...ev, recibido: new Date().toISOString() }, ...(s.eventos || [])].slice(0, 30);
const total = s.correctos + s.incorrectos;
const mensaje = ev.correcto
  ? '¡Correcto! ' + ev.residuo + ' clasificado. Precisión: ' + Math.round(100 * s.correctos / total) + '%'
  : 'Incorrecto: ' + ev.residuo + ' no va en ' + ev.contenedor + '.';
return [{ json: { mensaje, explicacion: KB[ev.tipo] || '', correctos: s.correctos, incorrectos: s.incorrectos, total, tasaPlanta: tasa } }];

const KB = {
  Plastico: 'Plástico (contenedor BLANCO): botellas PET, envases y bolsas limpias y secas. Aplástalos para ahorrar espacio.',
  Papel: 'Papel y cartón (contenedor AZUL): cajas, periódicos y hojas limpias. Si está grasoso o mojado ya no es reciclable.',
  Vidrio: 'Vidrio (contenedor VERDE): botellas y frascos sin tapa. Los focos y espejos NO van aquí.',
  Metal: 'Metales (contenedor AMARILLO): latas de aluminio y conservas, enjuagadas. El metal se recicla infinitas veces.',
  Organico: 'Orgánicos (contenedor MARRÓN): restos de fruta, verdura y cáscaras. Se convierten en compost.',
  NoAprovechable: 'No aprovechables (contenedor NEGRO): papel higiénico, envolturas metalizadas y residuos sucios. Van al relleno sanitario.',
  Peligroso: 'Peligrosos (contenedor ROJO): pilas, focos fluorescentes y medicinas. Contienen metales pesados: nunca a la basura común.'
};
const q = $input.first().json.query || {};
const tipo = q.tipo && KB[q.tipo] ? q.tipo : null;
const explicacion = tipo
  ? (q.residuo ? q.residuo + ' → ' : '') + KB[tipo]
  : 'Pregúntame por un residuo usando ?tipo=Plastico|Papel|Vidrio|Metal|Organico|NoAprovechable|Peligroso';
return [{ json: { mensaje: 'Chatbot de reciclaje', explicacion } }];

const rows = $input.all().map(i => i.json).filter(r => r.VC_MES && r.VC_MES !== 'TOTAL');
let aprov = 0, noAprov = 0;
for (const r of rows) { aprov += parseFloat(r.MO_RESIDUOS_APROVECHABLES); noAprov += parseFloat(r.MO_RESIDUOS_NO_APROVECHABLES); }
const tasa = Math.round(10000 * aprov / (aprov + noAprov)) / 100;
const s = $getWorkflowStaticData('global');
const c = s.correctos || 0, x = s.incorrectos || 0, t = c + x;
const tipos = Object.entries(s.porTipo || {}).map(([k, v]) => '<tr><td>' + k + '</td><td>' + v + '</td></tr>').join('');
const evs = (s.eventos || []).map(e => '<tr><td>' + e.recibido + '</td><td>' + e.residuo + '</td><td>' + e.tipo + '</td><td>' + e.contenedor + '</td><td>' + (e.correcto ? '✅' : '❌') + '</td></tr>').join('');
const meses = rows.map(r => '<tr><td>' + r.VC_MES + '</td><td>' + r.MO_RESIDUOS_NO_APROVECHABLES + '</td><td>' + r.MO_RESIDUOS_APROVECHABLES + '</td></tr>').join('');
const html = '<!doctype html><html lang="es"><head><meta charset="utf-8"><meta http-equiv="refresh" content="3"><title>Dashboard Planta de Reciclaje</title>'
 + '<style>body{font-family:Segoe UI,Arial;background:#10161c;color:#e8eef2;margin:24px}h1{color:#3cc8a0}.k{display:inline-block;background:#1c2630;padding:14px 22px;margin:6px;border-radius:8px;font-size:22px}table{border-collapse:collapse;margin:10px 0 24px}td,th{border:1px solid #2c3a46;padding:6px 12px}th{background:#1c2630}</style></head><body>'
 + '<h1>Planta de Reciclaje – ODS 12</h1><p>Eventos de clasificación enviados desde la simulación VR (Unity) y procesados por n8n.</p>'
 + '<div class="k">Total: ' + t + '</div><div class="k">Correctos: ' + c + '</div><div class="k">Incorrectos: ' + x + '</div><div class="k">Precisión: ' + (t ? Math.round(100 * c / t) : 0) + '%</div>'
 + '<h2>Eventos por tipo de residuo</h2><table><tr><th>Tipo</th><th>Eventos</th></tr>' + tipos + '</table>'
 + '<h2>Últimos eventos</h2><table><tr><th>Recibido</th><th>Residuo</th><th>Tipo</th><th>Contenedor</th><th>OK</th></tr>' + evs + '</table>'
 + '<h2>Datos abiertos: residuos municipales San Juan de Miraflores 2026 (t)</h2><table><tr><th>Mes</th><th>No aprovechables</th><th>Aprovechables</th></tr>' + meses + '</table>'
 + '<p>Tasa de reaprovechamiento del distrito: <b>' + tasa + '%</b>. Fuente: datosabiertos.gob.pe (ODC-BY).</p></body></html>';
return [{ json: { html } }];
